interface Analytics {
  totalUsers: number
  activeSessions: number
  revenue: number
}

interface Notification {
  id: string
  message: string
  read: boolean
}

interface Settings {
  theme: string
  notificationsEnabled: boolean
  language: string
}

interface DashboardData {
  analytics: Analytics
  notifications: Notification[]
  settings: Settings
}

async function getDashboardData(): Promise<DashboardData> {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('/api/analytics').then((r) => r.json()),
      fetch('/api/notifications').then((r) => r.json()),
      fetch('/api/settings').then((r) => r.json()),
    ])

    return { analytics, notifications, settings }
  } catch {
    return {
      analytics: { totalUsers: 0, activeSessions: 0, revenue: 0 },
      notifications: [],
      settings: { theme: 'system', notificationsEnabled: true, language: 'en' },
    }
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        <p>Total users: {analytics.totalUsers}</p>
        <p>Active sessions: {analytics.activeSessions}</p>
        <p>Revenue: ${analytics.revenue}</p>
      </section>

      <section>
        <h3>Notifications</h3>
        {notifications.length === 0 ? (
          <p>No notifications</p>
        ) : (
          <ul>
            {notifications.map((notification) => (
              <li key={notification.id}>
                {notification.read ? '✓' : '●'} {notification.message}
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
        <p>Notifications: {settings.notificationsEnabled ? 'On' : 'Off'}</p>
        <p>Language: {settings.language}</p>
      </section>
    </div>
  )
}

